<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../config/audit.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/tax_schedule_service.php';require_once __DIR__.'/report_error.php';
try{if($_SERVER['REQUEST_METHOD']!=='POST')jsonResponse(['success'=>false,'message'=>'Method not allowed'],405);$auth=requireAuth();$uid=authTenantId($auth);$actorId=authActorId($auth);$d=json_decode(file_get_contents('php://input'),true)?:[];$year=(int)($d['year']??0);$type=strtoupper(trim((string)($d['schedule_type']??'')));$reference=trim((string)($d['reference']??''));$description=trim((string)($d['description']??''));$date=(string)($d['event_date']??'');$beneficiary=trim((string)($d['beneficiary']??''));$gross=round((float)($d['gross_amount']??0),3);$opening=isset($d['opening_book_value'])&&$d['opening_book_value']!==''?round((float)$d['opening_book_value'],3):null;$rate=isset($d['annual_rate'])&&$d['annual_rate']!==''?round((float)$d['annual_rate'],6):null;$accounting=isset($d['accounting_amount'])&&$d['accounting_amount']!==''?round((float)$d['accounting_amount'],3):null;$fiscal=isset($d['fiscal_amount'])&&$d['fiscal_amount']!==''?round((float)$d['fiscal_amount'],3):null;$timing=strtoupper(trim((string)($d['timing']??'PERMANENT')));$legal=trim((string)($d['legal_basis']??''));$evidence=trim((string)($d['evidence_reference']??''));$notes=trim((string)($d['notes']??''));
    if($year<2000||$year>2200||!in_array($type,['DEPRECIATION','PROVISION','DONATION','SUBSIDY'],true)||$reference===''||$description===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||substr($date,0,4)!==(string)$year||!in_array($timing,['PERMANENT','TEMPORARY'],true)||$legal==='')throw new InvalidArgumentException('Year, type, reference, description, in-year date, timing, and legal basis are required');$calc=taxScheduleCalculation($type,$gross,$opening,$rate,$accounting,$fiscal);$conn=db();requirePermission($conn,$uid,'reports.view');$conn->begin_transaction();$closing=$calc['closing_book_value'];
    $s=$conn->prepare("INSERT INTO erp_tax_schedule_entries(user_id,fiscal_year,schedule_type,reference,description,event_date,beneficiary,gross_amount,opening_book_value,annual_rate,accounting_amount,fiscal_amount,fiscal_addition,fiscal_deduction,closing_book_value,timing,legal_basis,evidence_reference,notes,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'DRAFT',?)");$s->bind_param('iisssssddddddddssssi',$uid,$year,$type,$reference,$description,$date,$beneficiary,$gross,$opening,$rate,$calc['accounting_amount'],$calc['fiscal_amount'],$calc['fiscal_addition'],$calc['fiscal_deduction'],$closing,$timing,$legal,$evidence,$notes,$actorId);$s->execute();$id=(int)$s->insert_id;$s->close();auditLog($conn,$uid,$actorId,'TAX_SCHEDULE.ENTRY_ADDED','TAX_SCHEDULE_ENTRY',$id,null,['fiscal_year'=>$year,'schedule_type'=>$type,'reference'=>$reference,'gross_amount'=>$gross]+$calc);$conn->commit();jsonResponse(['success'=>true,'id'=>$id]+$calc);
}catch(Throwable $e){if(isset($conn))try{$conn->rollback();}catch(Throwable $ignored){}reportFailureResponse($e,'Could not save the tax schedule entry.','TAX_SCHEDULE_SAVE_FAILED');}
